CREATE OR REPLACE FUNCTION "honua".reject_append_only_mutation()
RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
END;
$$ LANGUAGE plpgsql

-- Service scope is immutable. Asset relinks are versioned mutations until completion
-- evidence pins the identity; the command layer enforces authorization.
CREATE OR REPLACE FUNCTION "honua".reject_task_identity_mutation()
RETURNS trigger AS $$
BEGIN
    IF NEW.service_id IS DISTINCT FROM OLD.service_id THEN
        RAISE EXCEPTION 'Task service is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF ROW(NEW.profile_id, NEW.asset_id) IS DISTINCT FROM ROW(OLD.profile_id, OLD.asset_id) THEN
        IF NEW.version <> OLD.version + 1
            OR OLD.status = 'completed'
            OR EXISTS (SELECT 1 FROM "honua".asset_inspections WHERE task_id = OLD.task_id)
            OR EXISTS (SELECT 1 FROM "honua".asset_service_records WHERE task_id = OLD.task_id) THEN
            RAISE EXCEPTION 'Task asset relink requires a new version and no completion evidence'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

-- NULL is a meaningful identity for unlinked service work, so a nullable composite FK alone
-- would not enforce this rule. The task FK still enforces existence and prevents deletion.
CREATE OR REPLACE FUNCTION "honua".check_completion_task_asset()
RETURNS trigger AS $$
DECLARE
    task_profile UUID;
    task_asset TEXT;
    task_kind TEXT;
BEGIN
    -- A new row version makes an older repeatable-read relinker fail serialization.
    -- The public version remains the version of the task command.
    UPDATE "honua".work_tasks SET version = version WHERE task_id = NEW.task_id
        RETURNING profile_id, asset_id, task_type INTO task_profile, task_asset, task_kind;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Completion task does not exist' USING ERRCODE = 'foreign_key_violation';
    END IF;
    -- One canonical record per task: inspections complete as inspections, all other types as service records.
    IF (TG_TABLE_NAME = 'asset_inspections') <> (task_kind = 'inspection') THEN
        RAISE EXCEPTION 'Completion record kind must match its task type' USING ERRCODE = 'check_violation';
    END IF;
    IF ROW(NEW.profile_id, NEW.asset_id) IS DISTINCT FROM ROW(task_profile, task_asset) THEN
        RAISE EXCEPTION 'Completion asset must match its task' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql
